"""Validate a portable NE-label/EPA-ecoregion research decision.

Caller must first authenticate the Neon snapshot and compile it with the reviewed
stage-three decision contract, then independently hash raw sources and resolve
current components. This adapter selects no cells and trusts no persisted root IDs.
"""
import hashlib,json,math,re
from urllib.parse import urlsplit
HEX=re.compile(r'^[a-f0-9]{64}$'); METHOD='label_contained_ecoregion_contact_v1'; REVIEWED_OPERATION_MANIFEST_SHA='141760e4b2a0b4a3b8006bcaf02758c726ca6def498c745cb728e9d18f93da65'
def need(v,m):
 if not v:raise ValueError(m)
def txt(x):return isinstance(x,str) and bool(x.strip())
def unique(rows,key,label):
 need(isinstance(rows,list) and len(rows)<=100000,'invalid '+label);out={}
 for r in rows:
  need(isinstance(r,dict),'invalid '+label);k=key(r);need(k not in out,'duplicate '+label);out[k]=r
 return out
def adapt(snapshot,compiled,selected_ids):
 need(isinstance(snapshot,dict) and snapshot.get('source')=='neon-export' and snapshot.get('schema')=='worldatlas-geography-decision-draft-evidence-v3','Neon snapshot required')
 need(not snapshot.get('schema','').endswith('-v3') or snapshot.get('unsupported_affiliation_source_ref_table_present') is False and snapshot.get('unsupported_point_methods_present') is False and snapshot.get('affiliation_source_refs')==[],'unsupported affiliation-source table status')
 rev=snapshot.get('decision_revision',{});erev=snapshot.get('entity_revision',{});need(rev.get('status')=='draft' and txt(rev.get('id')) and erev.get('status')=='draft' and rev.get('entity_revision')==erev.get('id'),'draft revisions required')
 need(isinstance(compiled,dict) and compiled.get('revision')==rev['id'] and compiled.get('entity_revision')==erev['id'] and isinstance(compiled.get('affiliation_ids'),list) and isinstance(compiled.get('affiliation_entry_links'),dict),'compiled decision contract required')
 need(isinstance(selected_ids,(set,frozenset)) and len(selected_ids)<=1000 and set(selected_ids)<=set(compiled['affiliation_ids']),'invalid selected IDs')
 aff=unique(snapshot.get('affiliations'),lambda x:x.get('affiliation_id'),'affiliations');features=unique(snapshot.get('features'),lambda x:x.get('feature_id'),'features');sources=unique(snapshot.get('sources'),lambda x:(x.get('source_id'),x.get('version')),'sources');assets=unique(snapshot.get('source_lineage_assets'),lambda x:(x.get('source_id'),x.get('version')),'source assets');entities=unique(snapshot.get('entities'),lambda x:x.get('id'),'entities');deps=snapshot.get('source_lineage_dependencies');need(isinstance(deps,list),'source lineage missing')
 need({k for k,a in aff.items() if a.get('method')==METHOD and a.get('evidence',{}).get('execution_status')=='selected_for_research'}==set(selected_ids),'selected method set mismatch')
 refs=snapshot.get('ecoregion_source_refs');need(isinstance(refs,list) and len(refs)<=10000,'ecoregion references missing');links={}
 for ref in refs:
  need(isinstance(ref,dict) and set(ref)=={'affiliation_id','source_id','source_version','role','decision_revision','contract'} and ref.get('decision_revision')==rev['id'] and ref.get('role')=='ecoregion' and ref.get('affiliation_id') in selected_ids and txt(ref.get('source_id')) and txt(ref.get('source_version')) and ref['affiliation_id'] not in links,'invalid or orphan ecoregion ref');links[ref['affiliation_id']]=ref
 def source(feature):
  k=(feature.get('source_id'),feature.get('source_version'));s=sources.get(k);a=assets.get(k);need(isinstance(s,dict) and isinstance(a,dict) and a.get('kind')=='raw' and a.get('provenance',{}).get('representation')=='provider_original' and not any(isinstance(d,dict) and (d.get('source_id'),d.get('version'))==k for d in deps),'invalid raw source provenance');need(all(s.get(k)==a.get(k) for k in ('sha256','size_bytes','r2_bucket','r2_key')) and isinstance(s.get('sha256'),str) and HEX.fullmatch(s['sha256']) and type(s.get('size_bytes')) is int and s['size_bytes']>0 and all(txt(s.get(k)) for k in ('r2_bucket','r2_key')),'invalid raw source custody');need(all(txt(a.get(k)) for k in ('source_uri','provider','attribution','license_name','license_uri')) and urlsplit(a['source_uri']).scheme=='https','invalid raw source metadata');return {**s,'source_uri':a['source_uri'],'provider':a['provider'],'attribution':a['attribution'],'license_name':a['license_name'],'license_uri':a['license_uri']}
 out=[]
 for aid in sorted(selected_ids):
  a=aff.get(aid);need(isinstance(a,dict) and a.get('decision_revision')==rev['id'] and a.get('scope')=='land' and a.get('relationship')=='affiliation' and a.get('method')==METHOD and a.get('evidence',{}).get('execution_status')=='selected_for_research' and compiled['affiliation_entry_links'].get(aid),'invalid selected affiliation or entry link')
  entity=entities.get(a.get('entity_id'));need(isinstance(entity,dict) and entity.get('level')=='continent' and entity.get('parent_id') is None and sum(b.get('entity_id')==a['entity_id'] and b.get('physical_class')=='land' for b in snapshot.get('category_bindings',[]))==1,'non-continent target')
  primary=features.get(a.get('feature_id'));secondary=links.get(aid);need(isinstance(primary,dict) and isinstance(secondary,dict),'missing primary label or ecoregion source');pe=primary.get('evidence',{});se=secondary.get('contract');need(txt(primary.get('source_feature_id')) and isinstance(primary.get('geometry_sha256'),str) and HEX.fullmatch(primary['geometry_sha256']) and pe.get('source_format')=='geojson' and txt(pe.get('selector_property')),'invalid label feature');need(isinstance(se,dict) and set(se)=={'source_format','source_crs','layer','selector_property','selector_value','name_property','name_value','expected_feature_count'} and se.get('source_format')=='esri-shapefile-zip' and se.get('source_crs')=='EPSG:3338' and all(txt(se.get(k)) for k in ('layer','selector_property','selector_value','name_property','name_value')) and type(se.get('expected_feature_count')) is int and 0<se['expected_feature_count']<=100000,'invalid ecoregion contract')
  sel=a['evidence'].get('selector');required={'partial_root_behavior','protected_root_behavior','untested_or_boundary_behavior','contact_rule','operations','operation_preference','pyproj_version','proj_version','label_expected_properties','operation_manifest_sha256'};need(isinstance(sel,dict) and set(sel)==required and sel['partial_root_behavior']=='exclude' and sel['protected_root_behavior']=='exclude' and sel['untested_or_boundary_behavior']=='exclude' and sel['contact_rule']=='at_least_one_strictly_inside_center' and txt(sel['pyproj_version']) and txt(sel['proj_version']) and isinstance(sel['label_expected_properties'],dict) and set(sel['label_expected_properties'])=={'NAME','FEATURECLA','REGION'} and all(txt(v) for v in sel['label_expected_properties'].values()),'invalid selector')
  ops=sel['operations'];need(isinstance(ops,list) and len(ops)==2 and all(isinstance(o,dict) and set(o)=={'id','pipeline','accuracy_m','scope','area_bounds'} and txt(o['id']) and txt(o['pipeline']) and txt(o['scope']) and type(o['accuracy_m']) in (int,float) and math.isfinite(o['accuracy_m']) and o['accuracy_m']>0 and isinstance(o['area_bounds'],dict) and set(o['area_bounds'])=={'west','east','south','north'} and all(type(v) in (int,float) and math.isfinite(v) for v in o['area_bounds'].values()) and -180<=o['area_bounds']['west']<=180 and -180<=o['area_bounds']['east']<=180 and -90<=o['area_bounds']['south']<=o['area_bounds']['north']<=90 for o in ops) and len({o['id'] for o in ops})==2,'invalid CRS operations');pref=sel['operation_preference'];need(isinstance(pref,list) and len(pref)==2 and set(pref)=={o['id'] for o in ops},'invalid operation preference');manifest={'operations':ops,'operation_preference':pref,'pyproj_version':sel['pyproj_version'],'proj_version':sel['proj_version']};digest=hashlib.sha256(json.dumps(manifest,sort_keys=True,separators=(',',':'),ensure_ascii=False,allow_nan=False).encode()).hexdigest();need(digest==sel['operation_manifest_sha256']==REVIEWED_OPERATION_MANIFEST_SHA,'unreviewed operation manifest')
  out.append({'affiliation_id':aid,'entity_id':a['entity_id'],'method':METHOD,'label':{'feature':primary,'source':source(primary)},'ecoregion':{'contract':se,'source':source(secondary)},'selector':sel,'limitations':['Center containment and coarse ecoregion contact do not prove whole-component island membership.','Operation bounding boxes do not establish exact transformation applicability.','Protected roots and partial label roots must be excluded, and conflicting claims must fail closed.']})
 return {'schema':'stage3-label-ecoregion-research-decisions-v1','status':'requires-source-resolution','revision':rev['id'],'decisions':out}
